["graffitty.navigator"] = "local M = {}\nlocal directions = { left = \"h\", down = \"j\", up = \"k\", right = \"l\" }\nlocal select_flags = { left = \"-L\", down = \"-D\", up = \"-U\", right = \"-R\" }\nlocal config = { modes = { \"n\" }, tmux = \"auto\", command = vim.env.GRAFFITTY_BIN or \"gft\" }\n-- Neovim owns its keys. Only a confirmed editor edge can leave the editor.\nfunction M.step(direction)\n  local key = assert(directions[direction], \"Invalid navigation direction\")\n  local mode = vim.api.nvim_get_mode()\n  local short = mode.mode:sub(1, 1)\n  if mode.blocking or (short == \"n\" and mode.mode ~= \"n\" and mode.mode ~= \"nt\") or not vim.tbl_contains(config.modes, short) or vim.fn.pumvisible() == 1\n    or vim.fn.getcmdwintype() ~= \"\" or vim.bo.buftype == \"prompt\"\n    or vim.api.nvim_win_get_config(0).relative ~= \"\" then return \"pass\" end\n  local before = vim.api.nvim_get_current_win()\n  if short == \"i\" or short == \"t\" then vim.cmd.stopinsert() end\n  local ok = pcall(vim.cmd.wincmd, key)\n  if not ok then return \"pass\" end\n  return before == vim.api.nvim_get_current_win() and \"edge\" or \"moved\"\nend\n\nlocal function tmux_edge(direction)\n  if not vim.env.TMUX or not vim.env.TMUX_PANE then return \"edge\" end\n  if config.tmux == false then return \"pass\" end\n  local socket = vim.env.TMUX:match(\"^[^,]+\")\n  local function run(args)\n    local cmd = { \"tmux\", \"-S\", socket }\n    vim.list_extend(cmd, args)\n    local ok, r = pcall(function() return vim.system(cmd, { text = true }):wait(1000) end)\n    if not ok then return nil end\n    return r.code == 0 and vim.trim(r.stdout or \"\") or nil\n  end\n  local edge = ({ left = \"left\", down = \"bottom\", up = \"top\", right = \"right\" })[direction]\n  local state = run({ \"display-message\", \"-p\", \"-t\", vim.env.TMUX_PANE,\n    \"#{pane_at_\" .. edge .. \"}:#{window_zoomed_flag}:#{pane_in_mode}\" })\n  if not state then return \"pass\" end\n  local at_edge, zoomed, in_mode = state:match(\"^(%d):(%d):(%d+)$\")\n  if not at_edge or in_mode ~= \"0\" then return \"pass\" end\n  if at_edge == \"1\" or zoomed == \"1\" then return \"edge\" end\n  return run({ \"select-pane\", \"-t\", vim.env.TMUX_PANE,\n    select_flags[direction] }) and \"moved\" or \"pass\"\nend\n\nlocal function graffitty_edge(direction)\n  -- tmux may have acquired its Graffitty environment after Neovim started;\n  -- the short-lived CLI resolves the current client context at the boundary.\n  if not vim.env.GRAFFITTY_SOCKET and not vim.env.TMUX then return \"edge\" end\n  if vim.fn.executable(config.command) ~= 1 then return \"edge\" end\n  local ok, result = pcall(function()\n    return vim.system({ config.command, \"pane\", \"select\", select_flags[direction] }, { text = true }):wait(2000)\n  end)\n  if not ok or result.code ~= 0 then return \"pass\" end\n  local decoded, response = pcall(vim.json.decode, result.stdout or \"\")\n  return decoded and type(response) == \"table\" and type(response.result) == \"table\"\n    and response.result.outcome or \"edge\"\nend\nfunction M.move_to(direction)\n  assert(directions[direction], \"Invalid navigation direction: expected left, down, up, or right\")\n  local result = M.step(direction)\n  -- Only an editor refusal permits literal delivery. A failed external call\n  -- may already have moved focus, so it must never replay the original key.\n  if result == \"pass\" then\n    local literal = vim.api.nvim_replace_termcodes(\"<C-\" .. directions[direction] .. \">\", true, false, true)\n    vim.api.nvim_feedkeys(literal, \"n\", false)\n    return result\n  end\n  if result == \"edge\" then result = tmux_edge(direction) end\n  if result == \"edge\" then result = graffitty_edge(direction) end\n  return result\nend\nfunction M.move_left() return M.move_to(\"left\") end\nfunction M.move_down() return M.move_to(\"down\") end\nfunction M.move_up() return M.move_to(\"up\") end\nfunction M.move_right() return M.move_to(\"right\") end\n\nfunction M.setup(opts)\n  config = vim.tbl_extend(\"force\", config, opts or {})\nend\nreturn M\n",
["graffitty.send.content_grabber"] = "-- Selection semantics adapted from tmux-send.nvim. Use Neovim's region\n-- reader for multibyte text, exclusive selection and ragged visual blocks.\nlocal M = {}\nlocal function get_visual_selection()\n  local mode = vim.fn.mode():sub(1, 1)\n  mode = ({ s = \"v\", S = \"V\", [string.char(19)] = string.char(22) })[mode] or mode\n  return vim.fn.getregion(vim.fn.getpos(\"v\"), vim.fn.getpos(\".\"), {\n    type = mode, exclusive = vim.o.selection == \"exclusive\",\n  })\nend\n\n---Grab content based on the filetype, vim mode, etc.\n---For example, if the filetype is NvimTree, then grab the full path of the file\n---In select/visual mode, grab the selected text.\n---In other modes, grab the line under the cursor.\n---@return string[]\nM.smart_grab = function()\n  -- NvimTree is open. Get the file path instead of copying the content.\n  if vim.bo.filetype == \"fyler_finder\" then\n    local finder = require(\"fyler.finder\")\n    local instance = finder.instance_get_or_nil()\n    local entry = instance and finder.parse_cursor_line(instance)\n    return entry and { \" \" .. vim.fn.shellescape(entry.path) } or {}\n  elseif vim.bo.filetype == \"NvimTree\" then\n    local nt_api = require(\"nvim-tree.api\")\n    local path = nt_api.tree.get_node_under_cursor().absolute_path\n    if path == nil then\n      local nt_nodes = nt_api.tree.get_nodes()\n      path = nt_nodes.absolute_path -- root dir path\n    end\n    return { \" \" .. vim.fn.shellescape(path) }\n  elseif vim.bo.filetype == \"neo-tree\" then\n    local node = require(\"neo-tree.sources.manager\").get_state(\"filesystem\").tree:get_node()\n    if node.path ~= nil then\n      return { \" \" .. vim.fn.shellescape(node.path) }\n    end\n\n    -- if you are on a message like (2 hidden items), then return empty\n    return {}\n  elseif vim.bo.filetype == \"oil\" then\n    local oil = require(\"oil\")\n    local entry = oil.get_cursor_entry()\n    if entry == nil then\n      return {}\n    end\n\n    local path = oil.get_current_dir() .. entry.name\n    return { \" \" .. vim.fn.shellescape(path) }\n  end\n\n  local mode = vim.api.nvim_get_mode().mode\n  -- \\22 is the ASCII code for CTRL-V (^V)\n  if vim.list_contains({ \"v\", \"V\", \"vs\", \"Vs\", \"s\", \"S\", \"CTRL-V\", \"\\22\", \"CTRL-S\", string.char(19) }, mode) then\n    return get_visual_selection()\n  else\n    return { vim.fn.getline(\".\") }\n  end\nend\n\nreturn M\n",
["graffitty.send"] = "-- Adapted from kiyoon/tmux-send.nvim (MIT; see LICENSE).\nlocal M = {}\nlocal config = { command = vim.env.GRAFFITTY_BIN or \"gft\", target = nil }\nlocal previous\n\nfunction M.setup(opts)\n  config = vim.tbl_extend(\"force\", config, opts or {})\nend\n\nfunction M.rpc(method, params)\n  local output = vim.fn.system({ config.command, \"rpc\", method, \"--params\", vim.json.encode(params or {}) })\n  local ok, response = pcall(vim.json.decode, output)\n  if vim.v.shell_error ~= 0 or not ok or type(response) ~= \"table\" or response.error then\n    local message = ok and type(response) == \"table\" and response.error and response.error.message or output\n    vim.notify(tostring(message), vim.log.levels.ERROR, { title = \"graffitty.nvim\" })\n    return nil\n  end\n  return response.result or response\nend\n\n---Same count convention as tmux-send: 5 = pane 5, 12 = tab 1 pane 2.\n---Stable IDs use count_is_uid or pane_identifier = \"%12\".\nfunction M.send_to_pane(opts)\n  opts = opts or {}\n  local target = opts.pane_identifier\n  if not target then\n    local count = vim.v.count\n    if count > 0 then\n      if opts.count_is_uid then target = \"%\" .. count\n      elseif count < 10 then target = \".\" .. count\n      else target = \":\" .. math.floor(count / 10) .. \".\" .. (count % 10) end\n    else\n      target = previous or config.target or \"connected\"\n    end\n  end\n  local content = opts.content\n  if content == nil then content = require(\"graffitty.send.content_grabber\").smart_grab() end\n  if type(content) == \"table\" then content = table.concat(content, \"\\n\") end\n  if type(content) ~= \"string\" or content == \"\" then return end\n  local result = M.rpc(\"pane.send\", { target = target, text = content, enter = opts.add_newline ~= false })\n  if result then previous = result.pane or target end\n  return result\nend\n\nfunction M.save_to_clipboard()\n  local content = require(\"graffitty.send.content_grabber\").smart_grab()\n  vim.fn.setreg(\"+\", content)\n  return content\nend\n\nreturn M\n"
